:root {
  font-family: "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  color: #18202b;
  background: #fbfcfe;
  font-synthesis: none;
  --ink: #18202b;
  --muted: #667085;
  --line: #dfe4ec;
  --line-soft: #edf0f5;
  --paper: #ffffff;
  --mist: #f4f6fa;
  --blue: #3156d9;
  --blue-soft: #eef2ff;
  --blue-line: #bdcafd;
  --cinnabar: #d65a45;
  --green: #2b8a68;
  --topbar-height: 72px;
}

/* Western classical astrology V1 closure */
.astrology-v1-guide { max-width:1480px; margin:0 0 38px; padding:24px; border:1px solid #d9d7cf; border-radius:20px; background:#f7f4ed; }
.astrology-v1-guide > header { display:flex; justify-content:space-between; align-items:end; gap:20px; margin-bottom:16px; }
.astrology-v1-guide > header small,.astrology-v1-closure small,.astrology-v1-guide footer strong { color:#a47132; font-size:11px; font-weight:800; letter-spacing:.08em; }
.astrology-v1-guide > header h2 { margin:5px 0 0; color:#253044; font:700 23px/1.3 "Songti SC",serif; }
.astrology-v1-guide > header > strong { display:grid; color:#405675; font:700 32px/1 Georgia,serif; text-align:right; }
.astrology-v1-guide > header > strong span { margin-top:4px; color:#737d87; font:700 10px/1.2 system-ui,sans-serif; }
.astrology-v1-stages { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; }
.astrology-v1-stages article { min-width:0; padding:18px; border:1px solid #dedbd3; border-radius:14px; background:#fff; }
.astrology-v1-stages i { color:#a47132; font:700 9px/1 ui-monospace,monospace; font-style:normal; }
.astrology-v1-stages h3 { margin:9px 0 6px; color:#253044; font:700 17px/1.25 "Songti SC",serif; }
.astrology-v1-stages p,.astrology-v1-closure p,.astrology-v1-guide footer p { margin:0; color:#737d87; font-size:11px; line-height:1.65; }
.astrology-v1-stages nav { display:flex; flex-wrap:wrap; gap:5px; margin-top:13px; }
.astrology-v1-stages button { padding:6px 8px; border:1px solid #dde1e7; border-radius:999px; color:#405675; background:#f5f7fa; font-size:10px; cursor:pointer; }
.astrology-v1-stages button:hover { border-color:#a47132; color:#7d5427; background:#fbf4e8; }
.astrology-v1-glossary { margin-top:8px; padding:18px; border:1px solid #d8d5cb; border-radius:14px; background:#fff; }
.astrology-v1-glossary > header { display:flex; justify-content:space-between; gap:16px; margin-bottom:12px; }.astrology-v1-glossary > header small { color:#a47132; font-size:10px; font-weight:800; }.astrology-v1-glossary > header strong { color:#737d87; font-size:10px; font-weight:600; }
.astrology-v1-glossary > div { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:7px; }.astrology-v1-glossary article { display:grid; gap:5px; padding:11px 12px; border-radius:10px; background:#f3f5f8; }.astrology-v1-glossary b { color:#405675; font:700 13px/1.2 "Songti SC",serif; }.astrology-v1-glossary span { color:#737d87; font-size:9px; line-height:1.5; }
.astrology-v1-closure { display:grid; grid-template-columns:1.05fr 1.3fr 1fr; gap:8px; margin-top:8px; }
.astrology-v1-closure article { padding:16px 18px; border:1px solid #dedbd3; border-radius:13px; background:#fff; }
.astrology-v1-closure article > div { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:5px 9px; margin-top:8px; }
.astrology-v1-closure span { color:#405675; font-size:10px; line-height:1.45; }
.astrology-v1-closure p { margin-top:8px; }
.astrology-v1-guide footer { display:flex; gap:14px; align-items:baseline; margin-top:8px; padding:14px 17px; border-left:3px solid #405675; background:#eef1f5; }
.astrology-completion-concepts { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; }
.astrology-completion-concepts article { display:grid; align-content:start; gap:8px; min-height:210px; padding:18px; border:1px solid #dedbd3; border-radius:14px; background:#fff; }
.astrology-completion-concepts i { color:#a47132; font:700 9px/1 ui-monospace,monospace; font-style:normal; }.astrology-completion-concepts small { color:#a47132; font-size:9px; }.astrology-completion-concepts strong { color:#253044; font:700 17px/1.25 "Songti SC",serif; }.astrology-completion-concepts p { margin:0; color:#737d87; font-size:10px; line-height:1.55; }
.astrology-completion-concepts article > div { display:flex; flex-wrap:wrap; gap:5px; margin-top:auto; }.astrology-completion-concepts span { padding:5px 7px; border-radius:999px; color:#405675; background:#eef1f5; font-size:8px; }
.astrology-completion-samples nav { display:flex; gap:6px; overflow-x:auto; padding-bottom:6px; scrollbar-width:thin; }
.astrology-completion-samples nav button { flex:0 0 auto; padding:9px 12px; border:1px solid #dedbd3; border-radius:999px; color:#68727c; background:#fff; font-size:10px; cursor:pointer; }.astrology-completion-samples nav button.active { color:#fff; border-color:#405675; background:#405675; }
.astrology-completion-stage { display:grid; grid-template-columns:1fr 28px 1.25fr; align-items:stretch; gap:8px; padding:17px; border:1px solid #d8d5cb; border-radius:17px; background:#f6f3eb; }
.astrology-completion-stage article { min-width:0; display:grid; align-content:center; gap:8px; min-height:120px; padding:17px; border:1px solid #dedbd3; border-radius:12px; background:#fff; }.astrology-completion-stage article:last-of-type { color:#fff; border-color:#405675; background:#405675; }.astrology-completion-stage small { color:#a47132; font-size:8px; }.astrology-completion-stage article:last-of-type small { color:#ead8b3; }.astrology-completion-stage strong { overflow-wrap:anywhere; color:#253044; font:700 15px/1.4 "Songti SC",serif; }.astrology-completion-stage article:last-of-type strong { color:#fff; }.astrology-completion-stage span { color:rgba(255,255,255,.7); font-size:9px; }.astrology-completion-stage > i { align-self:center; color:#a47132; font-style:normal; text-align:center; }
.astrology-completion-comparisons > div:last-child { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; }.astrology-completion-comparisons article { display:grid; align-content:start; gap:9px; padding:17px; border:1px solid #dedbd3; border-radius:12px; background:#fff; }.astrology-completion-comparisons strong { color:#253044; font:700 15px/1.25 "Songti SC",serif; }.astrology-completion-comparisons p { display:grid; gap:4px; margin:0; color:#737d87; font-size:9px; line-height:1.5; }.astrology-completion-comparisons p small { color:#a47132; font-size:8px; }.astrology-completion-comparisons article > span { padding-top:8px; border-top:1px solid #e1ded6; color:#405675; font-size:9px; font-weight:700; line-height:1.5; }
.astrology-node-links nav { display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:8px; }.astrology-node-links button { min-width:0; display:grid; grid-template-columns:minmax(0,1fr) auto; gap:5px 12px; padding:15px 16px; border:1px solid #d9dde5; border-radius:12px; color:#253044; background:#fff; text-align:left; cursor:pointer; }.astrology-node-links button:hover { border-color:#a47132; background:#fbf7ef; }.astrology-node-links button small { color:#a47132; font-size:8px; }.astrology-node-links button strong { font:700 14px/1.3 "Songti SC",serif; }.astrology-node-links button span { color:#737d87; font-size:9px; line-height:1.45; }.astrology-node-links button i { grid-column:2; grid-row:1/4; align-self:center; }.astrology-node-links svg { width:16px; fill:none; stroke:#a47132; stroke-width:1.8; }

@media (max-width: 760px) {
  .astrology-v1-guide { padding:17px; }.astrology-v1-guide > header { align-items:start; }.astrology-v1-guide > header h2 { font-size:20px; }.astrology-v1-stages,.astrology-v1-closure,.astrology-v1-glossary > div { grid-template-columns:1fr; }.astrology-v1-glossary > header { display:grid; gap:5px; }.astrology-v1-guide footer { display:grid; gap:6px; }
  .astrology-completion-concepts,.astrology-completion-comparisons > div:last-child { grid-template-columns:1fr; }.astrology-completion-concepts article { min-height:0; }.astrology-completion-stage { grid-template-columns:1fr; }.astrology-completion-stage > i { transform:rotate(90deg); }
}

/* 梅花第四批：卦形翻转、六爻骨架与时间精度边界。 */
.meihua-cuo-zong-preview,
.meihua-position-preview,
.meihua-precise-preview {
  border-color: #d9ded8;
  background: #f5f7f4;
}
.meihua-cuo-zong-preview { display:grid; grid-template-columns:1fr 34px 1.15fr; align-items:center; gap:6px; padding:15px; }
.meihua-cuo-zong-preview > span,
.meihua-cuo-zong-preview > div span { display:grid; place-items:center; gap:5px; padding:10px; border:1px solid #d9ded8; border-radius:12px; background:#fff; text-align:center; }
.meihua-cuo-zong-preview > span b { color:#4f6a60; font:400 23px/1.05 "Songti SC",serif; }
.meihua-cuo-zong-preview > i { color:#a65f42; font:700 8px/1.35 "Songti SC",serif; font-style:normal; text-align:center; }
.meihua-cuo-zong-preview > div { display:grid; gap:5px; }
.meihua-cuo-zong-preview > div span:last-child { color:#fff; border-color:#4f6a60; background:#4f6a60; }
.meihua-cuo-zong-preview small { color:#8b938e; font-size:8px; }
.meihua-cuo-zong-preview > div span:last-child small { color:rgba(255,255,255,.65); }
.meihua-cuo-zong-preview > div b { color:#a65f42; font:400 15px/1 "Songti SC",serif; }
.meihua-cuo-zong-preview strong { font:700 10px/1.2 "Songti SC",serif; }
.meihua-position-preview { display:grid; gap:8px; padding:14px; }
.meihua-position-preview > div { display:grid; gap:3px; }
.meihua-position-preview > div span { display:grid; grid-template-columns:20px 1fr 28px; align-items:center; gap:7px; min-height:24px; padding:2px 8px; border-radius:6px; background:#fff; }
.meihua-position-preview > div span.middle { color:#fff; background:#4f6a60; }
.meihua-position-preview span small { color:#a65f42; font:700 8px/1 ui-monospace,monospace; }
.meihua-position-preview span i { border-top:3px solid currentColor; }
.meihua-position-preview span b { font:700 9px/1 "Songti SC",serif; text-align:right; }
.meihua-position-preview footer { display:grid; grid-template-columns:repeat(3,1fr); gap:4px; }
.meihua-position-preview footer span { padding:6px; border-radius:999px; color:#4f6a60; background:#fff; font-size:8px; text-align:center; }
.meihua-precise-preview { display:grid; grid-template-columns:1fr 24px 1fr; align-items:stretch; gap:5px; padding:15px; }
.meihua-precise-preview section { display:grid; align-content:center; gap:7px; padding:13px; border:1px solid #d9ded8; border-radius:12px; background:#fff; }
.meihua-precise-preview section:last-child { color:#fff; border-color:#4f6a60; background:#4f6a60; }
.meihua-precise-preview small { color:#a65f42; font-size:8px; }
.meihua-precise-preview section:last-child small { color:#efc4b2; }
.meihua-precise-preview strong { font:700 11px/1.3 "Songti SC",serif; }
.meihua-precise-preview i { color:#808983; font-size:8px; font-style:normal; line-height:1.5; }
.meihua-precise-preview section:last-child i { color:rgba(255,255,255,.68); }
.meihua-precise-preview > b { align-self:center; color:#a65f42; font:700 13px/1 ui-monospace,monospace; text-align:center; }
.meihua-cuo-zong-detail,
.meihua-line-position-detail,
.meihua-precise-time-detail { --mh-ink:#263349; --mh-jade:#4f6a60; --mh-cinnabar:#a65f42; }
.meihua-cuo-example-selector,
.meihua-position-relation-selector { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:7px; margin-bottom:9px; }
.meihua-precision-selector { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; margin-bottom:9px; }
.meihua-cuo-example-selector button,
.meihua-position-relation-selector button,
.meihua-precision-selector button { display:grid; align-content:center; gap:6px; min-height:76px; padding:13px 15px; border:1px solid #d9ded9; border-radius:11px; color:#6e7972; background:#fff; text-align:left; cursor:pointer; }
.meihua-cuo-example-selector small,
.meihua-position-relation-selector small,
.meihua-precision-selector small { color:var(--mh-cinnabar); font-size:8px; line-height:1.35; }
.meihua-cuo-example-selector strong,
.meihua-position-relation-selector strong,
.meihua-precision-selector strong { color:var(--mh-ink); font:700 14px/1.25 "Songti SC",serif; }
.meihua-cuo-example-selector button.active,
.meihua-position-relation-selector button.active,
.meihua-precision-selector button.active { color:#fff; border-color:var(--mh-jade); background:var(--mh-jade); }
.meihua-cuo-example-selector button.active small,
.meihua-cuo-example-selector button.active strong,
.meihua-position-relation-selector button.active small,
.meihua-position-relation-selector button.active strong,
.meihua-precision-selector button.active small,
.meihua-precision-selector button.active strong { color:#fff; }
.meihua-operation-selector { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; margin-bottom:9px; }
.meihua-operation-selector button { min-height:102px; display:grid; grid-template-columns:1fr auto; align-content:center; gap:7px 14px; padding:17px; border:1px solid #d8ded9; border-radius:14px; color:#768078; background:#f5f7f4; text-align:left; cursor:pointer; }
.meihua-operation-selector small { color:var(--mh-cinnabar); font-size:9px; }
.meihua-operation-selector strong { grid-column:2; grid-row:1/3; color:var(--mh-ink); font:700 28px/1 "Songti SC",serif; }
.meihua-operation-selector span { max-width:390px; font-size:9px; line-height:1.5; }
.meihua-operation-selector button.active { color:#fff; border-color:var(--mh-jade); background:var(--mh-jade); }
.meihua-operation-selector button.active small,
.meihua-operation-selector button.active strong { color:#fff; }
.meihua-cuo-zong-stage { display:grid; grid-template-columns:minmax(0,1fr) 150px minmax(0,1fr); align-items:center; gap:10px; padding:18px; border:1px solid #d6dcd7; border-radius:22px; background:#f5f7f4; }
.meihua-cuo-zong-stage > div { display:grid; place-items:center; gap:10px; text-align:center; }
.meihua-cuo-zong-stage > div small { color:#78827b; font-size:9px; line-height:1.55; }
.meihua-cuo-zong-stage > div strong { display:grid; place-items:center; width:88px; aspect-ratio:1; border-radius:50%; color:#fff; background:var(--mh-cinnabar); font:700 18px/1 "Songti SC",serif; }
.meihua-cuo-zong-stage > div span { color:var(--mh-jade); font-size:9px; font-weight:700; }
.meihua-operation-note { display:flex; justify-content:space-between; gap:12px; margin:8px 0 0; padding:13px 16px; border-left:3px solid var(--mh-cinnabar); color:#737e77; background:#f6f4ef; font-size:9px; }
.meihua-operation-note strong { color:var(--mh-ink); }
.meihua-inverse-pairs > div:last-child { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; }
.meihua-inverse-pairs article { display:grid; grid-template-columns:1fr auto 1fr; place-items:center; gap:9px; padding:18px; border:1px solid #d9ded9; border-radius:12px; background:#fff; }
.meihua-inverse-pairs b { color:var(--mh-jade); font:700 27px/1 "Songti SC",serif; }
.meihua-inverse-pairs i { color:var(--mh-cinnabar); font-style:normal; }
.meihua-inverse-pairs span { grid-column:1/-1; color:#78827b; font-size:9px; }
.meihua-line-position-stage { display:grid; grid-template-columns:230px minmax(0,1fr); gap:10px; padding:18px; border:1px solid #d6dcd7; border-radius:22px; background:#f5f7f4; }
.meihua-line-position-stage > aside { display:grid; align-content:start; gap:10px; }
.meihua-line-position-stage > aside p { margin:0; padding:12px 14px; border-left:3px solid var(--mh-cinnabar); color:#747f78; background:#fff; font-size:9px; line-height:1.55; }
.meihua-line-position-stage > section { display:grid; gap:9px; }
.meihua-line-position-stage header { display:grid; grid-template-columns:auto 1fr; gap:5px 14px; padding:16px; border-radius:14px; color:#fff; background:var(--mh-jade); }
.meihua-line-position-stage header small { color:#efc4b2; font-size:8px; }
.meihua-line-position-stage header strong { font:700 20px/1 "Songti SC",serif; }
.meihua-line-position-stage header p { grid-column:1/-1; margin:0; color:rgba(255,255,255,.7); font-size:9px; line-height:1.5; }
.meihua-line-position-stage section > div { display:grid; gap:4px; }
.meihua-line-position-stage section article { display:grid; grid-template-columns:28px 65px 65px 1fr; align-items:center; gap:9px; min-height:47px; padding:6px 12px; border:1px solid #dde2de; border-radius:9px; background:#fff; }
.meihua-line-position-stage section article.middle { box-shadow:inset 3px 0 0 var(--mh-jade); }
.meihua-line-position-stage section article.moving { border-color:var(--mh-cinnabar); }
.meihua-line-position-stage article small { color:var(--mh-cinnabar); font:700 8px/1 ui-monospace,monospace; }
.meihua-line-position-stage article > span { display:flex; gap:7px; }
.meihua-line-position-stage article > span i { width:25px; border-top:4px solid var(--mh-ink); }
.meihua-line-position-stage article > span.yin i { width:18px; }
.meihua-line-position-stage article strong { color:var(--mh-ink); font:700 13px/1 "Songti SC",serif; }
.meihua-line-position-stage article b { justify-self:end; color:var(--mh-jade); font:700 11px/1.2 "Songti SC",serif; }
.meihua-position-ledger > div:last-child { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:7px; }
.meihua-position-ledger article { display:grid; align-content:start; gap:8px; padding:17px; border:1px solid #d9ded9; border-radius:12px; background:#fff; }
.meihua-position-ledger article.active { border-color:var(--mh-jade); box-shadow:inset 0 3px 0 var(--mh-jade); }
.meihua-position-ledger small { color:var(--mh-cinnabar); font-size:8px; }
.meihua-position-ledger strong { color:var(--mh-ink); font:700 16px/1.2 "Songti SC",serif; }
.meihua-position-ledger p { margin:0; color:#747f78; font-size:9px; line-height:1.55; }
.meihua-precise-clock { display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:5px 16px; margin-bottom:9px; padding:19px 22px; border:1px solid #d7ddd8; border-radius:18px; background:#f5f7f4; }
.meihua-precise-clock small { color:var(--mh-cinnabar); font-size:8px; }
.meihua-precise-clock strong { color:var(--mh-ink); font:700 17px/1.2 "Songti SC",serif; }
.meihua-precise-clock b { grid-column:3; grid-row:1/3; color:var(--mh-jade); font:700 30px/1 ui-monospace,monospace; letter-spacing:-2px; }
.meihua-precise-clock span { grid-column:1/3; color:#758078; font-size:9px; }
.meihua-precision-formulas { display:grid; grid-template-columns:1fr 30px 1fr 30px 1fr; align-items:stretch; gap:6px; padding:17px; border:1px solid #d6dcd7; border-radius:20px; background:#f5f7f4; }
.meihua-precision-formulas article { min-height:135px; display:grid; align-content:center; gap:8px; padding:17px; border:1px solid #d9ded9; border-radius:13px; background:#fff; }
.meihua-precision-formulas article small { color:var(--mh-cinnabar); font-size:8px; }
.meihua-precision-formulas article strong { color:var(--mh-ink); font:700 20px/1 "Songti SC",serif; }
.meihua-precision-formulas article p { margin:0; color:#737e77; font-size:9px; line-height:1.5; }
.meihua-precision-formulas article span { color:var(--mh-jade); font-size:9px; font-weight:700; }
.meihua-precision-formulas > i { align-self:center; color:var(--mh-cinnabar); font-style:normal; text-align:center; }
.meihua-precision-result { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)) 1.25fr; gap:7px; margin-top:9px; }
.meihua-precision-result article,
.meihua-precision-result aside { min-height:112px; display:grid; place-items:center; align-content:center; gap:6px; padding:14px; border:1px solid #d9ded9; border-radius:12px; background:#fff; }
.meihua-precision-result aside { color:#fff; border-color:var(--mh-jade); background:var(--mh-jade); }
.meihua-precision-result small { color:var(--mh-cinnabar); font-size:8px; }
.meihua-precision-result aside small { color:#efc4b2; }
.meihua-precision-result article strong { color:var(--mh-ink); font:700 25px/1 ui-monospace,monospace; }
.meihua-precision-result aside strong { font:700 20px/1.2 "Songti SC",serif; }
.meihua-precision-result span { color:#77827a; font-size:9px; }
.meihua-precision-result aside span { color:rgba(255,255,255,.7); }
.meihua-field-reassignment > div:last-child { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; }
.meihua-field-reassignment article { display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:8px; padding:17px; border:1px solid #d9ded9; border-radius:12px; background:#fff; }
.meihua-field-reassignment article > strong { grid-column:1/-1; color:var(--mh-ink); font:700 17px/1.2 "Songti SC",serif; }
.meihua-field-reassignment p { display:grid; gap:5px; margin:0; color:#747f78; font-size:9px; line-height:1.5; }
.meihua-field-reassignment small { color:var(--mh-cinnabar); font-size:8px; }
.meihua-field-reassignment i { color:var(--mh-jade); font-style:normal; }
.meihua-sensitivity-board nav { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
