* { box-sizing: border-box; }
.app-shell small { font-size: 12px; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: #fbfcfe; }
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, a:focus-visible, article:focus-visible, input:focus-visible { outline: 3px solid rgba(49, 86, 217, .22); outline-offset: 3px; }

.topbar {
  height: var(--topbar-height); position: sticky; top: 0; z-index: 20; display: flex; align-items: center;
  gap: 24px; padding: 0 28px; border-bottom: 1px solid var(--line-soft); background: rgba(255,255,255,.93);
  backdrop-filter: blur(18px);
}
.brand { display: flex; align-items: center; gap: 10px; border: 0; background: transparent; font-weight: 760; font-size: 18px; cursor: pointer; padding: 0; }
.brand-mark { width: 33px; height: 33px; position: relative; display: inline-block; }
.brand-mark i { position: absolute; width: 23px; height: 23px; display: grid; place-items: center; border-radius: 8px; color: white; font: 700 12px/1 "Songti SC", serif; font-style: normal; }
.brand-mark i:first-child { background: var(--ink); left: 0; top: 0; }
.brand-mark i:last-child { background: var(--blue); right: 0; bottom: 0; box-shadow: 0 0 0 3px white; }
.primary-nav { display: flex; align-items: center; gap: 5px; }
.primary-nav button { border: 0; background: transparent; padding: 10px 12px; border-radius: 10px; color: #4b5565; cursor: pointer; white-space: nowrap; }
.primary-nav button.active { color: var(--blue); font-weight: 650; }
.primary-nav .topic-switcher { background: #f3f4f6; color: var(--ink); }
.primary-nav .map-switcher span { margin-left: 10px; color: #8d96a4; }
.topic-switcher strong { color: var(--blue); margin-left: 4px; }
.topic-switcher span { margin-left: 12px; }
.map-menu, .topic-menu { position: relative; }
.map-menu-panel, .topic-menu-panel { position: absolute; top: calc(100% + 13px); left: 0; z-index: 30; padding: 13px; border: 1px solid var(--line); border-radius: 17px; background: rgba(255,255,255,.98); box-shadow: 0 22px 60px rgba(24,32,43,.16); backdrop-filter: blur(18px); }
.map-menu-panel { width: 310px; }
.topic-menu-panel { position: absolute; top: calc(100% + 13px); left: 0; z-index: 30; width: 340px; max-height: calc(100vh - 92px); padding: 13px; overflow-y: auto; overscroll-behavior: contain; border: 1px solid var(--line); border-radius: 17px; background: rgba(255,255,255,.98); box-shadow: 0 22px 60px rgba(24,32,43,.16); backdrop-filter: blur(18px); }
.topic-menu-panel > small { display: block; padding: 7px 10px 13px; color: #778292; font-size: 13px; letter-spacing: .04em; }
.primary-nav .map-menu-panel > button, .primary-nav .topic-menu-panel > button { width: 100%; min-height: 68px; display: flex; align-items: center; justify-content: space-between; padding: 10px 12px; border-radius: 12px; text-align: left; }
.primary-nav .map-menu-panel > button:hover, .primary-nav .topic-menu-panel > button:hover { color: var(--ink); background: var(--blue-soft); }
.map-menu-panel button > span, .topic-menu-panel button > span { display: grid; gap: 7px; margin: 0; }
.map-menu-panel button strong, .topic-menu-panel button strong { color: var(--ink); font-size: 16px; }
.map-menu-panel button small, .topic-menu-panel button small { color: #8a93a1; font-size: 12px; }
.map-menu-panel button i, .topic-menu-panel button i { color: var(--blue); font-style: normal; }
.topbar-actions { display: flex; align-items: center; gap: 7px; margin-left: auto; padding-left: 18px; border-left: 1px solid var(--line-soft); }
.topbar-actions > button, .topbar-actions > a { height: 40px; display: inline-flex; align-items: center; padding: 0 11px; border: 0; border-radius: 10px; color: #687385; background: transparent; font-size: 14px; text-decoration: none; white-space: nowrap; }
.topbar-actions > a, .topbar-actions .group-placeholder { cursor: pointer; }
.topbar-actions .group-placeholder { padding: 0 14px; border: 1px solid #cee9dd; color: #287758; background: #f0faf5; }
.topbar-actions .temperature-home { padding: 0 15px; border: 1px solid #c8d3f7; color: var(--blue); background: #f2f5ff; font-weight: 750; }
.topbar-actions .search-trigger { width: 40px; display: grid; place-items: center; padding: 0; border: 1px solid var(--line); border-radius: 50%; background: white; cursor: pointer; }
.search-trigger svg { width: 17px; fill: none; stroke: #687385; stroke-width: 2; }
.search-box { position: absolute; top: calc(100% + 10px); right: 28px; z-index: 31; width: min(380px, calc(100vw - 32px)); height: 44px; display: flex; align-items: center; gap: 9px; padding: 0 14px; border: 1px solid #ccd5e6; border-radius: 23px; background: rgba(255,255,255,.98); box-shadow: 0 18px 45px rgba(24,32,43,.14); opacity: 0; visibility: hidden; pointer-events: none; transform: translateY(-7px); transition: opacity .16s ease, transform .16s ease, visibility .16s ease; }
.search-box.open { opacity: 1; visibility: visible; pointer-events: auto; transform: translateY(0); }
.search-box svg { width: 17px; fill: none; stroke: #98a2b3; stroke-width: 2; }
.search-box input { min-width: 0; flex: 1; border: 0; outline: 0; color: var(--ink); background: transparent; }
.search-box input::placeholder { color: #a4aab4; }
.search-box kbd { font-size: 12px; color: #98a2b3; border: 1px solid var(--line); border-radius: 5px; padding: 2px 5px; }

.follow-banner { position: relative; min-height: 62px; display: flex; align-items: center; justify-content: center; padding: 8px 72px; border-bottom: 1px solid #eadfca; color: #6f4c27; background: linear-gradient(90deg, #fffaf0, #fff7e8 50%, #fffaf3); }
.follow-banner-entry { display: flex; align-items: center; gap: 14px; padding: 0; border: 0; color: inherit; background: transparent; cursor: pointer; }
.follow-banner-entry > p { display: flex; align-items: baseline; gap: 10px; margin: 0; text-align: left; }
.follow-banner strong { font: 700 15px/1.3 "Songti SC", serif; }
.follow-banner p span { color: #8b6a46; font-size: 13px; }
.follow-banner-entry > i { padding-left: 2px; color: #3156d9; font-size: 12px; font-style: normal; font-weight: 700; }
.follow-banner-close { position: absolute; right: 28px; width: 32px; height: 32px; border: 0; border-radius: 50%; color: #aa8a67; background: transparent; font-size: 20px; cursor: pointer; }
.follow-banner-close:hover { background: rgba(151,103,48,.08); }
.contact-qr-preview { position: relative; flex: 0 0 auto; width: 42px; height: 42px; display: block; overflow: hidden; border: 1px solid #d7c29f; border-radius: 6px; background: white; }
.contact-qr-preview img { width: 100%; height: 100%; display: block; object-fit: cover; }
.follow-dock { position: fixed; z-index: 16; left: 16px; bottom: 16px; width: 216px; display: grid; grid-template-columns: 54px minmax(0,1fr); align-items: center; gap: 11px; padding: 11px; border: 1px solid #dfe3ea; border-radius: 13px; color: inherit; background: rgba(255,255,255,.96); box-shadow: 0 14px 40px rgba(29,39,61,.13); backdrop-filter: blur(14px); cursor: pointer; text-align: left; }
.follow-dock:hover { border-color: #bdc9e9; box-shadow: 0 17px 46px rgba(29,39,61,.17); transform: translateY(-2px); }
.follow-dock .contact-qr-preview { width: 54px; height: 54px; }
.follow-dock > p { min-width: 0; margin: 0; }
.follow-dock strong, .follow-dock span { display: block; }
.follow-dock strong { color: #2f3a4a; font: 700 14px/1.3 "Songti SC", serif; }
.follow-dock span { margin-top: 6px; color: #8a93a0; font-size: 11px; line-height: 1.45; }

.contact-panel-backdrop { position: fixed; inset: 0; z-index: 80; display: grid; place-items: center; padding: 24px; background: rgba(23,31,43,.52); backdrop-filter: blur(10px); }
.contact-panel { width: min(900px, 100%); max-height: calc(100dvh - 48px); overflow-y: auto; border: 1px solid rgba(255,255,255,.7); border-radius: 24px; background: #fbfcfe; box-shadow: 0 34px 90px rgba(15,23,42,.28); }
.contact-panel.contact-only { width: min(540px, 100%); }
.contact-panel > header { display: flex; align-items: flex-start; justify-content: space-between; gap: 30px; padding: 30px 34px 24px; border-bottom: 1px solid var(--line); background: linear-gradient(135deg, #f3f6ff, #fffaf1); }
.contact-panel > header small { color: var(--blue); font-weight: 750; letter-spacing: .08em; }
.contact-panel > header h2 { margin: 8px 0 7px; color: var(--ink); font: 700 30px/1.25 "Songti SC", serif; }
.contact-panel > header p { margin: 0; color: #6c7685; font-size: 13px; }
.contact-panel > header button { flex: 0 0 auto; width: 38px; height: 38px; border: 1px solid var(--line); border-radius: 50%; color: #7a8492; background: rgba(255,255,255,.8); font-size: 22px; cursor: pointer; }
.contact-panel-grid { display: grid; grid-template-columns: .9fr 1.1fr; gap: 14px; padding: 18px; }
.contact-panel-grid.single { grid-template-columns: 1fr; }
.contact-card { min-width: 0; display: grid; grid-template-rows: auto 1fr auto; gap: 16px; padding: 22px; border: 1px solid var(--line); border-radius: 17px; background: white; }
.contact-card > div small { color: #8a94a2; font-size: 11px; letter-spacing: .1em; }
.contact-card h3 { margin: 7px 0 8px; color: var(--ink); font: 700 22px/1.2 "Songti SC", serif; }
.contact-card > div p { margin: 0; color: #697483; font-size: 13px; line-height: 1.65; }
.contact-card figure { min-width: 0; margin: 0; display: grid; place-items: center; align-content: center; gap: 10px; padding: 14px; border-radius: 12px; background: #f5f7fa; }
.contact-card figure img { display: block; max-width: 100%; max-height: 360px; object-fit: contain; }
.contact-card.wecom figure img { width: min(300px, 100%); }
.contact-card.feishu-group figure img { width: min(380px, 100%); max-height: 480px; }
.contact-card figcaption { color: #7e8794; font-size: 11px; }
.contact-card > a { min-height: 42px; display: flex; align-items: center; justify-content: space-between; padding: 0 14px; border-radius: 10px; color: white; background: var(--ink); font-size: 13px; font-weight: 700; text-decoration: none; }
.contact-card.wecom > a { background: #287758; }
.contact-card.feishu-group > a { background: #3370ff; }
.contact-panel.group-panel { width: min(570px, 100%); }

.page-layout { min-height: calc(100vh - var(--topbar-height)); display: grid; grid-template-columns: 232px minmax(0, 1fr); }
.sidebar { position: sticky; top: var(--topbar-height); height: calc(100vh - var(--topbar-height)); padding: 36px 24px 26px 30px; border-right: 1px solid var(--line-soft); background: rgba(255,255,255,.84); overflow-y: auto; }
.sidebar-kicker { color: var(--blue); font-size: 12px; font-weight: 700; letter-spacing: .08em; margin-bottom: 28px; }
.sidebar section { margin-bottom: 23px; }
.sidebar h2 { margin: 0 0 8px; color: #9198a5; font-size: 12px; letter-spacing: .08em; font-weight: 700; }
.side-item { width: 100%; min-height: 34px; display: flex; justify-content: space-between; align-items: center; margin: 2px 0; padding: 7px 9px; border: 0; border-radius: 8px; background: transparent; font: inherit; font-size: 14px; color: #4d5665; text-align: left; }
button.side-item { cursor: pointer; }
button.side-item:hover { background: var(--mist); color: #263244; }
button.side-item:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
button.side-item:active { transform: translateY(1px); }
.side-item.active { background: var(--blue-soft); color: var(--blue); }
.side-item small { font-size: 12px; color: #abb1bb; }
.side-arrow { color: #a2aab7; font-size: 18px; line-height: 1; opacity: 0; transform: translateX(-3px); transition: opacity .15s ease, transform .15s ease; }
button.side-item:hover .side-arrow, button.side-item:focus-visible .side-arrow { opacity: 1; transform: translateX(0); }
.side-item.unavailable { color: #a5abb5; }
.muted-group { opacity: .66; }

.global-layout { min-height: calc(100vh - var(--topbar-height)); display: grid; grid-template-columns: 232px minmax(0, 1fr); }
.map-sidebar { position: sticky; top: var(--topbar-height); height: calc(100vh - var(--topbar-height)); padding: 36px 24px 26px 30px; border-right: 1px solid var(--line-soft); background: rgba(255,255,255,.9); }
.map-sidebar nav { display: grid; gap: 5px; }
.map-sidebar nav button { min-height: 42px; display: flex; align-items: center; justify-content: space-between; padding: 0 10px; border: 0; border-radius: 9px; background: transparent; color: #596273; cursor: pointer; text-align: left; }
.map-sidebar nav button:hover { background: var(--mist); }
.map-sidebar nav button.active { color: var(--blue); background: var(--blue-soft); font-weight: 700; }
.map-sidebar nav small { min-width: 23px; height: 23px; display: grid; place-items: center; border-radius: 50%; color: #8992a2; background: #f2f4f7; font-size: 12px; }
.map-sidebar nav button.active small { color: var(--blue); background: white; }
.mobile-lens-nav { display: none; }

.overview-main { padding: 62px clamp(30px, 5vw, 86px) 100px; overflow: hidden; background-image: linear-gradient(rgba(59,89,190,.045) 1px, transparent 1px), linear-gradient(90deg, rgba(59,89,190,.045) 1px, transparent 1px); background-size: 56px 56px; background-position: 0 14px; }
.overview-main::before { content: ""; position: fixed; z-index: -1; width: 650px; height: 330px; left: 32%; top: 60px; background: radial-gradient(ellipse, rgba(101,124,229,.12), transparent 68%); pointer-events: none; }
.page-heading { max-width: 760px; margin-bottom: 32px; }
.eyebrow { color: var(--blue); text-transform: uppercase; font-size: 12px; letter-spacing: .1em; font-weight: 720; margin: 0 0 12px; }
.page-heading h1 { font: 700 clamp(38px, 4vw, 58px)/1.12 "Songti SC", "STSong", serif; letter-spacing: -.04em; margin: 0; }
.page-heading > p:last-child { margin: 0; max-width: 650px; color: var(--muted); font-size: 17px; line-height: 1.8; }
.map-breadcrumb { display: flex; align-items: center; gap: 4px; margin: 0 0 26px; padding: 0; border: 0; background: transparent; color: #7e8796; font-size: 12px; cursor: pointer; }
.map-breadcrumb svg { width: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.section-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 22px; border-bottom: 1px solid var(--line); padding-bottom: 14px; }
.section-heading > div:first-child { display: flex; align-items: baseline; gap: 10px; }
.section-heading h2 { font-size: 25px; margin: 0; }
.section-heading span { color: #9aa1ad; font-size: 13px; }
.topic-learning-path { max-width: 1480px; margin: 0 0 38px; padding: 22px 24px; border: 1px solid #d9dee7; border-radius: 17px; background: rgba(255,255,255,.96); }
.topic-learning-path header { display: flex; align-items: baseline; gap: 12px; margin-bottom: 17px; }
.topic-learning-path header small { color: var(--blue); font-size: 12px; font-weight: 750; letter-spacing: .08em; }
.topic-learning-path h2 { margin: 0; font: 700 21px/1.3 "Songti SC", serif; }
.topic-learning-path > div { display: flex; align-items: center; gap: 7px; overflow-x: auto; padding-bottom: 5px; scrollbar-width: thin; }
.topic-learning-path button { flex: 0 0 auto; display: flex; align-items: center; gap: 7px; min-height: 38px; padding: 6px 11px 6px 7px; border: 1px solid #dce2ec; border-radius: 20px; color: #4d5868; background: white; cursor: pointer; }
.topic-learning-path button:hover { color: var(--blue); border-color: var(--blue-line); background: var(--blue-soft); }
.topic-learning-path button i { width: 24px; height: 24px; display: grid; place-items: center; border-radius: 50%; color: white; background: var(--blue); font: normal 11px/1 ui-monospace, monospace; }
.topic-learning-path button span { font-size: 13px; font-weight: 700; }
.topic-learning-path b { color: #abb3bf; font-size: 12px; }
.topic-learning-path > p { margin: 11px 0 0; color: #8992a0; font-size: 12px; }
.personality-learning-path > div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;overflow:visible}.personality-learning-path button{width:100%;min-width:0;border-radius:10px}.personality-learning-path button span{white-space:normal;text-align:left}.personality-learning-path>div>b{display:none}
.card-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; max-width: 1480px; }
.knowledge-card { container-type: inline-size; position: relative; min-width: 0; min-height: 410px; padding: 25px; border: 1px solid #d9dee7; border-radius: 18px; background: rgba(255,255,255,.96); box-shadow: 0 1px 2px rgba(18,27,50,.03); cursor: pointer; overflow: hidden; transition: transform .2s ease, border-color .2s ease, box-shadow .2s ease; }
.knowledge-card:hover { transform: translateY(-4px); border-color: #b8c4ed; box-shadow: 0 18px 40px rgba(28,45,104,.09); }
.card-topline { display: flex; justify-content: space-between; color: #7a8393; font-size: 12px; margin-bottom: 19px; }
.card-topline span { color: var(--blue); font-weight: 650; }
.knowledge-card h3 { margin: 0; font-size: 24px; letter-spacing: -.02em; }
.knowledge-card h3 em, .detail-article h1 em { font-style: normal; font-weight: 500; color: var(--blue); font-size: .66em; margin-left: 7px; }
.detail-article h1 em { display: block; margin: 10px 0 0; font-family: Georgia, "Times New Roman", serif; font-size: .42em; line-height: 1.2; letter-spacing: 0; }
.knowledge-card blockquote { position: relative; margin: 13px 0 20px; min-height: 48px; padding-left: 22px; color: #596273; font-size: 14px; line-height: 1.65; }
.knowledge-card blockquote::before { content: "“"; position: absolute; left: 0; top: -7px; color: #718bef; font: 700 30px/1 Georgia, serif; }
.card-visual { width: 100%; min-width: 0; height: 190px; overflow: hidden; border: 1px solid #e7eaf0; border-radius: 14px; background-color: #fafbfc; background-image: linear-gradient(rgba(49,86,217,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(49,86,217,.035) 1px, transparent 1px); background-size: 24px 24px; }
.card-footer { display: flex; align-items: center; justify-content: space-between; margin-top: 20px; }
.card-footer > div { display: flex; gap: 6px; flex-wrap: wrap; }
.card-footer span { padding: 5px 8px; border-radius: 6px; background: #f3f5f8; color: #747d8b; font-size: 12px; }
.card-footer button { width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; background: white; color: var(--blue); }
.card-footer svg, .edge-nav svg, .back-button svg { width: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.card-index { position: absolute; right: 26px; top: 60px; font: 600 12px/1 ui-monospace, monospace; color: #bcc2cd; }
.empty-state { border: 1px dashed var(--line); border-radius: 16px; padding: 60px; text-align: center; color: var(--muted); background: white; }

