.framework-scope-grid strong { font: 700 20px/1.35 "Songti SC", serif; }
.framework-scope-grid p { margin: 0; color: #7a8492; font-size: 12px; line-height: 1.7; }
.framework-boundary { margin: 18px 0 0; padding: 16px 18px; border-radius: 11px; color: #66707e; background: #f5f7fa; font-size: 12px; line-height: 1.75; }

