/* Taiyi · Twenty-eight lodges and two nine-star systems */
.taiyi-lodge-layers,
.taiyi-lodge-ring > div,
.taiyi-lodge-routes > div,
.taiyi-lodge-audit > div,
.taiyi-nine-cycles > div,
.taiyi-nine-audit > div {
  display: grid;
  gap: 12px;
}

.taiyi-lodge-layers { grid-template-columns: repeat(5, minmax(0, 1fr)); margin: 22px 0 40px; }
.taiyi-lodge-layers article,
.taiyi-lodge-ring article,
.taiyi-lodge-routes article,
.taiyi-lodge-audit article,
.taiyi-nine-cycles article,
.taiyi-nine-audit article {
  border: 1px solid var(--line, #dfe5ef);
  border-radius: 14px;
  background: #fff;
  padding: 16px;
}
.taiyi-lodge-layers article > i { color: #446bf2; font-style: normal; font-size: 12px; font-weight: 800; }
.taiyi-lodge-layers header { display: flex; flex-direction: column; gap: 3px; margin: 12px 0; }
.taiyi-lodge-layers header small,
.taiyi-lodge-routes header small,
.taiyi-nine-cycles small { color: #73809a; }
.taiyi-lodge-layers header strong { font-size: 18px; }
.taiyi-lodge-layers article > b { color: #3159df; }
.taiyi-lodge-layers p,
.taiyi-lodge-routes p,
.taiyi-lodge-audit p,
.taiyi-nine-audit p { color: #59657a; line-height: 1.7; }

.taiyi-lodge-ring > div { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.taiyi-lodge-ring article header { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 14px; }
.taiyi-lodge-ring article section { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 5px; }
.taiyi-lodge-ring article section span { display: grid; place-items: center; aspect-ratio: 1; border-radius: 50%; background: #f2f5ff; color: #254cc9; font-weight: 800; }

.taiyi-lodge-anchors > div { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 8px; }
.taiyi-lodge-anchors > div > span { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 5px; padding: 12px 8px; border-radius: 10px; background: #f5f7fb; text-align: center; }
.taiyi-lodge-anchors i { color: #9aa5b8; font-style: normal; }
.taiyi-lodge-anchors strong { color: #3159df; }

.taiyi-lodge-routes > div { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.taiyi-lodge-routes header { display: grid; grid-template-columns: 1fr auto; gap: 5px 12px; align-items: end; }
.taiyi-lodge-routes header small { grid-column: 1 / -1; }
.taiyi-lodge-routes header b { color: #3159df; font-size: 12px; }
.taiyi-lodge-routes code { display: block; margin-top: 14px; padding: 10px; border-radius: 8px; background: #f4f6fb; color: #24385f; white-space: normal; }

.taiyi-lodge-methods nav,
.taiyi-nine-methods nav,
.taiyi-nine-system-selector { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; margin-bottom: 12px; }
.taiyi-nine-system-selector { grid-template-columns: repeat(2, minmax(0, 1fr)); margin: 20px 0 36px; }
.taiyi-lodge-methods nav button,
.taiyi-nine-methods nav button,
.taiyi-nine-system-selector button { display: flex; flex-direction: column; gap: 4px; padding: 13px; border: 1px solid #dfe5ef; border-radius: 11px; background: #fff; text-align: left; }
.taiyi-lodge-methods nav button.active,
.taiyi-nine-methods nav button.active,
.taiyi-nine-system-selector button.active { border-color: #446bf2; box-shadow: inset 0 3px #446bf2; background: #f7f9ff; }
.taiyi-lodge-methods nav small,
.taiyi-nine-methods nav small,
.taiyi-nine-system-selector small { color: #73809a; }
.taiyi-lodge-methods nav span,
.taiyi-nine-methods nav span,
.taiyi-nine-system-selector span { color: #3159df; font-size: 12px; }
.taiyi-lodge-methods > article,
.taiyi-nine-methods > article { border-radius: 14px; background: #172231; color: #fff; padding: 20px; }
.taiyi-lodge-methods > article header,
.taiyi-nine-methods > article header { display: flex; gap: 12px; align-items: baseline; }
.taiyi-lodge-methods > article header strong,
.taiyi-nine-methods > article header strong { font-size: 22px; }
.taiyi-lodge-methods > article header b,
.taiyi-nine-methods > article header b { margin-left: auto; color: #f3c66d; }
.taiyi-lodge-methods > article > div,
.taiyi-nine-methods > article > div { display: flex; align-items: center; gap: 12px; margin-top: 18px; }
.taiyi-lodge-methods > article span,
.taiyi-nine-methods > article span { display: flex; flex-direction: column; gap: 4px; color: #9caabd; }
.taiyi-lodge-methods > article span b,
.taiyi-nine-methods > article span b { color: #fff; font-size: 18px; }
.taiyi-lodge-methods > article i,
.taiyi-nine-methods > article i { color: #718199; font-style: normal; }

.taiyi-lodge-audit > div { grid-template-columns: repeat(5, minmax(0, 1fr)); }
.taiyi-lodge-audit footer { border-top: 1px solid #edf0f5; margin-top: 12px; padding-top: 12px; color: #9a5b2d; line-height: 1.6; }

.taiyi-nine-sequence > div { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); gap: 7px; }
.taiyi-nine-sequence > div span { display: flex; flex-direction: column; gap: 9px; align-items: center; padding: 15px 6px; border: 1px solid #dfe5ef; border-radius: 12px; background: #fff; }
.taiyi-nine-sequence span i { color: #8793a7; font-style: normal; font-size: 11px; }
.taiyi-nine-sequence span strong { color: #3159df; }
.taiyi-nine-sequence > footer { margin-top: 12px; color: #73809a; }
.taiyi-nine-cycles > div { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.taiyi-nine-cycles article { display: flex; flex-direction: column; gap: 10px; }
.taiyi-nine-cycles article span { color: #3159df; }
.taiyi-nine-cycles footer { border-top: 1px solid #edf0f5; padding-top: 10px; color: #825c30; }
.taiyi-nine-audit > div { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.taiyi-nine-audit article section { display: grid; grid-template-columns: 1fr auto 1fr; gap: 10px; margin-top: 12px; }
.taiyi-nine-audit article section span { padding: 11px; border-radius: 9px; background: #f4f6fb; color: #4d596d; line-height: 1.6; }
.taiyi-nine-audit article section small { display: block; color: #3159df; margin-bottom: 5px; }
.taiyi-nine-audit article section i { align-self: center; color: #b17c46; font-style: normal; }

@media (max-width: 720px) {
  .taiyi-lodge-layers,
  .taiyi-lodge-ring > div,
  .taiyi-lodge-routes > div,
  .taiyi-lodge-audit > div,
  .taiyi-nine-cycles > div,
  .taiyi-nine-audit > div { grid-template-columns: 1fr; }
  .taiyi-lodge-anchors > div { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .taiyi-lodge-methods nav,
  .taiyi-nine-methods nav { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .taiyi-nine-system-selector { grid-template-columns: 1fr; }
  .taiyi-lodge-methods > article > div,
  .taiyi-nine-methods > article > div { align-items: stretch; flex-direction: column; }
  .taiyi-lodge-methods > article > div > i,
  .taiyi-nine-methods > article > div > i { transform: rotate(90deg); align-self: center; }
  .taiyi-nine-sequence > div { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .taiyi-nine-audit article section { grid-template-columns: 1fr; }
  .taiyi-nine-audit article section i { transform: rotate(90deg); justify-self: center; }
}

/* Taiyi · Five tones and five movements / six qi */
.taiyi-tone-layers,
.taiyi-wuyun-layers { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin: 22px 0 40px; }
.taiyi-tone-layers article,
.taiyi-wuyun-layers article { border: 1px solid #dfe5ef; border-radius: 14px; background: #fff; padding: 16px; }
.taiyi-tone-layers article > i,
.taiyi-wuyun-layers article > i { color: #446bf2; font-style: normal; font-size: 12px; font-weight: 800; }
.taiyi-tone-layers header,
.taiyi-wuyun-layers header { display: flex; flex-direction: column; gap: 3px; margin: 12px 0; }
.taiyi-tone-layers header small,
.taiyi-wuyun-layers header small { color: #73809a; }
.taiyi-tone-layers header strong,
.taiyi-wuyun-layers header strong { font-size: 18px; }
.taiyi-tone-layers p,
.taiyi-wuyun-layers p { color: #59657a; line-height: 1.6; }
.taiyi-tone-layers b,
.taiyi-wuyun-layers b { color: #3159df; }

.taiyi-tone-maps > div,
.taiyi-wuyun-tables > div { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.taiyi-tone-maps section,
.taiyi-wuyun-tables section { border: 1px solid #dfe5ef; border-radius: 14px; background: #fff; padding: 16px; }
.taiyi-tone-maps section header,
.taiyi-wuyun-tables section header { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 14px; }
.taiyi-tone-maps section > span,
.taiyi-wuyun-tables section > span { display: grid; grid-template-columns: minmax(78px, .7fr) 1fr 1.2fr; align-items: center; gap: 10px; padding: 11px 0; border-top: 1px solid #edf0f5; }
.taiyi-tone-maps section > span > i,
.taiyi-wuyun-tables section > span > i { color: #3159df; font-style: normal; }
