.personality-card-preview {
  --ps-ink: #30343b;
  --ps-blue: #506480;
  --ps-aqua: #60786f;
  --ps-coral: #a6634c;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  align-items: end;
  min-height: 112px;
  padding: 13px;
  border-radius: 16px;
  background: #f3f1ec;
}
.personality-card-preview > span { min-width: 0; display: grid; align-content: end; gap: 5px; min-height: calc(48px + var(--personality-step) * 15px); padding: 10px; border:1px solid #ddd9d0; border-left:3px solid var(--ps-blue); border-radius:8px; color:var(--ps-ink); background:#fff; }
.personality-card-preview > span small { color: #71809a; font: 700 8px/1 ui-monospace, monospace; }
.personality-card-preview > span strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }
.personality-preview-questionnaire-length-and-versions > span { min-height: calc(42px + var(--personality-step) * 24px); border-left-color: var(--ps-aqua); }
.personality-preview-from-items-to-scores > span { min-height:58px; border-color:#d9d3c9; text-align:center; place-content:center; }
.personality-preview-domains-and-facets { align-items:center; background-image:radial-gradient(#c6c0b6 1px,transparent 1px); background-size:12px 12px; }
.personality-preview-neuroticism-emotional-reactivity > span { transform: translateY(calc((var(--personality-step) - 1) * -8px)); border-left-color: var(--ps-coral); }
.personality-preview-extraversion-social-energy > span { border-color:#b8ab8e; text-align:center; }
.personality-preview-openness-experience-and-ideas > span { border-left-color:#776f82; }
.personality-preview-agreeableness-interpersonal-orientation > span { border-left-color: var(--ps-aqua); }
.personality-preview-conscientiousness-self-management > span { border-top: 3px solid var(--ps-blue); border-left: 0; }
.personality-preview-raw-t-percentile-scores > span { border-left: 0; border-bottom: 4px solid var(--ps-blue); font: 700 18px/1 ui-monospace, monospace; }
.personality-preview-norm-groups-and-comparisons > span:nth-child(2) { color: #fff; background: var(--ps-ink); }
.personality-preview-response-quality-before-interpretation > span { border-left-color: var(--ps-coral); }
.personality-preview-reliability-validity-factor-structure > span { min-height: 78px; border-left-color: #8d74b8; }
.personality-preview-reading-a-trait-profile > span { border-left-color:var(--ps-aqua); }
.personality-preview-validated-scale-versus-project-quiz { grid-template-columns: 1fr .65fr 1fr; }
.personality-preview-validated-scale-versus-project-quiz > span:nth-child(2) { min-height: 34px; place-content: center; color: #fff; background: var(--ps-coral); }

.personality-detail { --ps-ink:#30343b; --ps-blue:#506480; --ps-aqua:#60786f; --ps-coral:#a6634c; --ps-violet:#776f82; --ps-paper:#f4f2ed; display:grid; gap:22px; color:var(--ps-ink); }
.personality-lab-intro { display:grid; gap:7px; padding:0; border:0; }
.personality-lab-intro small { color:var(--blue); font-size:10px; font-weight:800; letter-spacing:.08em; }
.personality-lab-intro h2 { max-width:880px; margin:0; font:700 clamp(22px,2.5vw,31px)/1.42 Georgia,'Songti SC',serif; }
.personality-use-rail { display:grid; grid-template-columns:1fr 1fr; gap:7px; border:0; }
.personality-use-rail section,.personality-use-rail aside { padding:15px 17px; border-left:3px solid var(--ps-aqua); background:var(--ps-paper); }
.personality-use-rail aside { border-left-color:var(--ps-coral); }
.personality-use-rail small { color:var(--ps-blue); font-size:9px; font-weight:800; letter-spacing:.08em; }
.personality-use-rail p { position:relative; margin:9px 0 0; padding-left:15px; color:#6e6a64; font-size:11px; line-height:1.55; }
.personality-use-rail p::before { position:absolute; left:0; content:'↳'; color:var(--ps-aqua); }
.personality-use-rail aside p::before { content:'×'; color:var(--ps-coral); }
.personality-verdict { margin:0; padding:15px 18px; border-left:4px solid var(--ps-aqua); background:var(--ps-paper); font-weight:700; line-height:1.65; }
.personality-situation-quote { display:grid; gap:9px; margin:0; padding:20px; border:1px solid #ddd9d0; border-left:4px solid var(--ps-blue); color:var(--ps-ink); background:#fff; font:700 clamp(17px,2vw,23px)/1.5 Georgia,'Songti SC',serif; }
.personality-situation-quote small { color:var(--ps-blue); font:800 9px/1 system-ui,sans-serif; }
.personality-situation-quote span { color:#6e6a64; font:400 11px/1.65 system-ui,sans-serif; }

.personality-lens { display:grid; grid-template-columns:1fr 90px 1fr; gap:20px; align-items:stretch; }
.personality-lens section { display:grid; gap:0; border:1px solid #cad2df; }
.personality-lens section small,.personality-lens section p { padding:15px 18px; }
.personality-lens section small { color:var(--ps-blue); font-weight:800; background:#edf1fa; }
.personality-lens section p { margin:0; border-top:1px solid #e0e5ed; line-height:1.55; }
.personality-lens > i { align-self:center; padding:15px 8px; border-radius:999px; color:#fff; background:var(--ps-aqua); text-align:center; font-size:10px; font-style:normal; }
.personality-lens article { display:grid; align-content:center; gap:10px; padding:22px; border:1px solid #ddd9d0; background:var(--ps-paper); }
.personality-lens article span { color:var(--ps-aqua); font-size:11px; font-weight:800; }
.personality-lens article strong { font:700 24px/1.25 Georgia,'Songti SC',serif; }
.personality-lens article p { margin:0; line-height:1.65; }

.personality-version-rack { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; align-items:end; }
.personality-version-rack button { display:grid; gap:10px; padding:20px; border:1px solid #d8d3ca; color:var(--ps-ink); background:#fff; text-align:left; cursor:pointer; }
.personality-version-rack button.active { border-color:var(--ps-aqua); box-shadow:inset 0 -4px var(--ps-aqua); background:#f0f2ee; }
.personality-version-rack strong { font:700 clamp(34px,4.5vw,52px)/.95 Georgia,serif; }
.personality-version-rack strong small { font:700 13px/1 system-ui,sans-serif; }
.personality-version-rack h3,.personality-version-rack p { margin:0; }
.personality-version-rack button>div { display:flex; gap:3px; align-items:end; height:42px; }
.personality-version-rack button>div i { flex:1; height:10px; background:var(--ps-aqua); }
.personality-version-rack button>div i:nth-child(2n) { height:22px; }.personality-version-rack button>div i:nth-child(3n) { height:34px; }
.personality-version-focus { display:grid; grid-template-columns:90px 180px 1fr; gap:12px; align-items:center; margin:0; padding:15px 18px; border-left:4px solid var(--ps-aqua); background:var(--ps-paper); }.personality-version-focus small{color:var(--ps-aqua);font-weight:800}.personality-version-focus span{color:#6e6a64;line-height:1.55}
.personality-version-decision { display:grid; grid-template-columns:1fr 1fr auto 1fr 1fr; align-items:center; border:1px solid #cad2df; }
.personality-version-decision>* { padding:18px; }.personality-version-decision b { color:var(--ps-blue); background:#edf1fa; }.personality-version-decision i { color:var(--ps-coral); font-style:normal; }

.personality-score-conveyor,.personality-score-transform { display:grid; grid-template-columns:1fr auto 1fr auto 1fr; gap:10px; align-items:center; }
.personality-score-conveyor article { display:grid; gap:10px; min-height:170px; padding:24px; border:1px solid #cad2df; background:#fff; }
.personality-score-conveyor article.active { color:#fff; background:var(--ps-aqua); }
.personality-score-conveyor>i { color:var(--ps-coral); font:700 15px/1 ui-monospace,monospace; font-style:normal; }
.personality-score-conveyor strong { font-size:23px; }.personality-score-conveyor span { font-size:11px; }
.personality-score-notes { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; }
.personality-score-notes p { margin:0; padding:18px; border-top:3px solid var(--ps-aqua); background:var(--ps-paper); line-height:1.6; }
.personality-score-notes i { display:block; margin-bottom:9px; color:var(--ps-aqua); font-style:normal; font-weight:800; }

.personality-domain-matrix { display:grid; grid-template-columns:repeat(5,1fr); gap:8px; }
.personality-domain-matrix article { display:grid; place-items:center; gap:12px; padding:18px 8px; border:1px solid #ddd9d0; border-top:4px solid var(--ps-blue); background:#fff; }
.personality-domain-matrix article>strong { font:700 28px/1 Georgia,serif; }.personality-domain-matrix article>div { display:grid; grid-template-columns:repeat(3,7px); gap:5px; }.personality-domain-matrix i { width:7px; height:7px; border-radius:50%; background:var(--ps-blue); }
.personality-same-score { display:grid; grid-template-columns:.5fr 1fr 1fr; border:1px solid #cad2df; }
.personality-same-score>* { padding:22px; }.personality-same-score header { display:grid; place-content:center; text-align:center; background:#edf1fa; }.personality-same-score header strong { font:700 50px/1 Georgia,serif; }
.personality-same-score article { display:grid; grid-template-columns:auto 1fr 1fr; gap:9px; border-left:1px solid #cad2df; }.personality-same-score article b { grid-row:1/3; font-size:28px; }.personality-same-score article span { padding:6px; text-align:center; background:#e8eaee; }.personality-same-score article span.high { color:#fff; background:var(--ps-blue); }.personality-same-score article p { grid-column:2/4; margin:0; line-height:1.55; }

.personality-trait-stage { display:grid; gap:20px; padding:24px; border:1px solid #ddd9d0; background:var(--ps-paper); }
.personality-trait-axis { display:grid; grid-template-columns:auto 1fr auto 1fr auto; align-items:center; gap:14px; }.personality-trait-axis i { height:2px; background:linear-gradient(90deg,#cfd6e2,var(--ps-blue)); }.personality-trait-axis span { font-weight:800; }
