.personality-trait-focus{display:grid;grid-template-columns:90px 110px 1fr;gap:10px;align-items:center;margin:0;padding:14px 16px;background:#fff}.personality-trait-focus small{color:var(--ps-blue);font-weight:800}.personality-trait-focus span{color:#6e6a64;line-height:1.5}
