.personality-score-transform { grid-template-columns:1fr auto 1fr auto 1fr auto 1fr; }
.personality-score-transform article { display:grid; place-items:center; gap:8px; min-height:145px; padding:16px; border:1px solid #ddd9d0; border-bottom:4px solid var(--ps-blue); background:#fff; text-align:center; }.personality-score-transform article strong { font:700 36px/1 Georgia,serif; }.personality-score-transform article span { color:#6e6a64; font-size:10px; }.personality-score-transform>i { color:var(--ps-coral); font:700 10px/1.4 ui-monospace,monospace; font-style:normal; }
