.personality-quality-decision { display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:15px; padding:28px; border:1px solid #cad2df; text-align:center; }.personality-quality-decision i { color:var(--ps-coral); font-size:38px; font-style:normal; }.personality-quality-decision strong { font-size:24px; }.personality-quality-decision p { grid-column:1/-1; margin:0; padding-top:18px; border-top:1px solid #cad2df; line-height:1.6; }.personality-quality-rules { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }.personality-quality-rules p { margin:0; padding:17px; background:var(--ps-paper); line-height:1.55; }

.personality-evidence-columns { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }.personality-evidence-columns article { display:grid; align-content:start; gap:10px; min-height:235px; padding:20px; border:1px solid #ddd9d0; border-top:5px solid var(--ps-blue); background:#fff; }.personality-evidence-columns article:nth-child(2) { border-top-color:var(--ps-aqua); }.personality-evidence-columns article:nth-child(3) { border-top-color:var(--ps-violet); }.personality-evidence-columns i { color:#8b867e; font-style:normal; }.personality-evidence-columns h3 { margin:0; font:700 26px/1 Georgia,'Songti SC',serif; }.personality-evidence-columns p { line-height:1.6; }.personality-evidence-columns small { margin-top:auto; padding-top:12px; border-top:1px solid #ddd9d0; color:var(--ps-coral); }
