.personality-profile-sheet { display:grid; grid-template-columns:.75fr 1.25fr; gap:20px; padding:28px; background:var(--ps-paper); }.personality-profile-sheet aside { display:grid; gap:14px; }.personality-profile-sheet aside span { display:grid; grid-template-columns:25px 1fr; align-items:center; gap:9px; }.personality-profile-sheet aside i { height:16px; background:linear-gradient(90deg,var(--ps-blue),#91a8e6); }.personality-profile-sheet section { display:grid; gap:8px; }.personality-profile-sheet article { display:grid; grid-template-columns:80px 1fr; gap:7px 15px; padding:16px; background:#fff; }.personality-profile-sheet article small { grid-row:1/3; color:var(--ps-blue); font-weight:800; }.personality-profile-sheet article p { margin:0; color:#68758b; }

.personality-comparison-table { border:1px solid #cad2df; }.personality-comparison-table header,.personality-comparison-table section { display:grid; grid-template-columns:.6fr 1fr 1fr; }.personality-comparison-table header { color:#fff; background:var(--ps-ink); }.personality-comparison-table>* > * { padding:17px; }.personality-comparison-table section>* { border-top:1px solid #cad2df; }.personality-comparison-table section span:last-child { background:#f5eff0; }.personality-comparison-table small { color:var(--ps-blue); font-weight:800; }.personality-no-conversion { display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:14px; text-align:center; }.personality-no-conversion strong { padding:25px; background:#edf1fa; }.personality-no-conversion i { color:var(--ps-coral); font-style:normal; font-weight:800; }

