  .personality-version-focus,.personality-trait-focus{grid-template-columns:1fr}.personality-trait-facets { grid-template-columns:repeat(3,1fr); }.personality-trait-facets button { min-height:58px; }.personality-trait-scene { grid-template-columns:1fr; }.personality-trait-scene blockquote,.personality-trait-scene p,.personality-trait-scene strong { grid-column:1; grid-row:auto; }
  .personality-score-transform { grid-template-columns:1fr; }.personality-score-transform>i { justify-self:center; }.personality-norm-questions,.personality-quality-console { grid-template-columns:repeat(2,1fr); }.personality-quality-console article:last-child { grid-column:1/-1; }.personality-evidence-case { grid-template-columns:1fr; }.personality-comparison-table { overflow-x:auto; }.personality-comparison-table header,.personality-comparison-table section { min-width:620px; }.personality-no-conversion { grid-template-columns:1fr; }
}


