/* 手机端应用外壳：把首屏留给知识，而不是固定导航。 */
@media (max-width:760px) {
  :root { --topbar-height:calc(64px + env(safe-area-inset-top)); }
  html { scroll-padding-top:calc(var(--topbar-height) + 12px); }
  body { min-width:320px; overflow-x:hidden; -webkit-text-size-adjust:100%; }
  button { -webkit-tap-highlight-color:transparent; }

  .topbar {
    height:var(--topbar-height); flex-wrap:nowrap; align-content:normal; gap:6px;
    padding:env(safe-area-inset-top) max(10px, env(safe-area-inset-right)) 0 max(10px, env(safe-area-inset-left));
  }
  .brand { flex:0 0 auto; min-height:44px; }
  .primary-nav { min-width:0; gap:3px; margin-left:auto; }
  .primary-nav > button { display:none; }
  .primary-nav .map-menu { display:block; }
  .primary-nav button { min-height:44px; padding:0 9px; font-size:12px; }
  .primary-nav .map-switcher span,
  .topic-switcher span { margin-left:4px; }
  .topic-switcher strong { margin-left:2px; }

  .topbar-actions { display:flex; flex:0 0 auto; gap:0; margin-left:0; padding-left:0; border-left:0; }
  .topbar-actions .nav-placeholder,
  .topbar-actions .group-placeholder,
  .topbar-actions .temperature-home { display:none; }
  .topbar-actions .search-trigger { width:42px; height:42px; display:grid; }

  .search-box,
  .search-box.open {
    position:absolute; top:calc(100% + 8px); right:12px; left:12px; z-index:32;
    order:initial; width:auto; height:48px; display:flex; flex:initial; margin:0;
    box-shadow:0 18px 45px rgba(24,32,43,.16);
  }
  .search-box { opacity:0; visibility:hidden; pointer-events:none; transform:translateY(-7px); }
  .search-box.open { opacity:1; visibility:visible; pointer-events:auto; transform:translateY(0); }
  .search-box input { font-size:16px; }
  .search-box kbd { display:none; }

  .map-menu-panel,
  .topic-menu-panel {
    position:fixed; top:calc(var(--topbar-height) + 8px); right:12px; left:12px; width:auto;
    max-height:calc(100dvh - var(--topbar-height) - 20px); padding:9px; overflow-y:auto;
    overscroll-behavior:contain;
  }
  .primary-nav .map-menu-panel > button,
  .primary-nav .topic-menu-panel > button { min-height:60px; }

  .follow-banner {
