  .follow-banner-close { right:max(4px, env(safe-area-inset-right)); width:44px; height:44px; }

  .overview-main { padding-right:max(16px, env(safe-area-inset-right)); padding-bottom:calc(70px + env(safe-area-inset-bottom)); padding-left:max(16px, env(safe-area-inset-left)); }
  .detail-main { padding-bottom:calc(92px + env(safe-area-inset-bottom)); }
