  .detail-article header blockquote { padding:16px 18px; font-size:15px; }
  .detail-article .lead { margin-bottom:36px; line-height:1.75; }
  .detail-rail { min-height:44px; margin-bottom:28px; }
  .detail-rail .back-button { min-height:44px; }
  .section-heading > div:first-child { min-width:0; flex-wrap:wrap; }
  .section-heading h2 { font-size:23px; }

  .mobile-lens-nav,
  .topic-learning-path > div,
  .plate-reading-guide,
  .meihua-relation-selector,
  .meihua-season-selector,
  .meihua-virtue-selector,
  .meihua-response-selector,
  .astrology-planet-selector,
  .astrology-aspect-selector,
  .astrology-predictive-technique-selector {
    scroll-snap-type:x proximity; -webkit-overflow-scrolling:touch;
  }
  .mobile-lens-nav button,
  .topic-learning-path button { min-height:44px; scroll-snap-align:start; }
  .mobile-lens-nav { padding-bottom:8px; }

  .knowledge-card,
  .method-card,
